'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const read = relative => fs.readFileSync(path.join(root, relative), 'utf8');

assert(fs.existsSync(path.join(root, 'n100n/server.js')), 'N100N server is vendored under KRA.');
assert(fs.existsSync(path.join(root, 'n100n/public/index.html')), 'N100N dashboard UI is included.');
assert(!fs.existsSync(path.join(root, 'n100n/.env')), 'N100N runtime secrets are not bundled.');
assert(!fs.existsSync(path.join(root, 'n100n/data/n100n.db')), 'N100N runtime database is not bundled.');
const upstream = read('n100n/UPSTREAM.md');
assert(upstream.includes('turtrsst/n100n') && upstream.includes('77fe26134c83103e3f4175a43cf852b91dacc8a1') && upstream.includes('00c81c836ed5181a2b696ce095b5f8ad8a4a99db'), 'Vendored upstream source is traceable to its base and auth commits.');
assert(read('n100n/.gitignore').includes('.env') && read('n100n/.gitignore').includes('data/'), 'N100N secrets and runtime data are ignored.');
assert(read('.htaccess').includes('RewriteRule ^n100n(?:/|$) - [F,L,NC]'), 'Apache does not expose the bundled Node source as static files.');
assert(read('web/index.html').includes('id="creator-n100n-open"'), 'Creator Studio has an N100N UI shortcut.');
const appSource = read('web/app.js');
assert(appSource.includes('url.username || url.password') && appSource.includes('browserOnLan') && appSource.includes('target.hostname') && appSource.includes("url.protocol === 'https:' && !localService"), 'The UI shortcut links only public HTTPS services or LAN/same-server endpoints (loopback rewritten to the LAN page host), and never credentialed/query URLs.');
assert(read('desktop/main.js').includes('startN100nServer') && read('desktop/main.js').includes('ensureN100nEnv'), 'The desktop shell auto-starts and pairs the bundled N100N sub-app.');
const n100nServer = read('n100n/server.js');
const n100nStore = read('n100n/lib/store.js');
const n100nUi = read('n100n/public/index.html');
const n100nDeployment = read('docs/N100N_DEPLOYMENT.md');
assert(n100nServer.includes("const VERSION = '1.3.0'") && n100nServer.includes("process.env.APP_PASSWORD || '123456'") && n100nServer.includes('APP_PASSWORD_RESET') && n100nServer.includes('/api/change-password') && n100nServer.includes('crypto.scryptSync'), 'N100N v1.3.0 stores a hashed admin password with bootstrap, UI change, and emergency reset flows.');
assert(n100nStore.includes('app_settings') && n100nStore.includes('getSetting(key)') && n100nStore.includes('setSetting(key, value)'), 'N100N persists settings such as the password hash in SQLite.');
assert(n100nUi.includes('id="changePasswordBtn"') && n100nUi.includes('id="passwordDialog"') && n100nUi.includes('Masuk ke workspace'), 'N100N includes the refreshed login page and password-change dialog.');
assert(fs.existsSync(path.join(root, 'n100n/tests/auth.test.js')) && fs.existsSync(path.join(root, 'n100n/tests/default-password.test.js')), 'N100N auth regression tests are bundled.');
assert(n100nDeployment.includes('https://automation.kantor-rama-ai.my.id') && n100nDeployment.includes('Update `automation.kantor-rama-ai.my.id` ke N100N v1.3.0'), 'The production automation hostname has an explicit v1.3.0 update runbook.');
const concatWorkflow = read('n100n/workflows/contoh-concat-edit.json');
assert(concatWorkflow.includes('project_create') && concatWorkflow.includes("'/call'") && fs.existsSync(path.join(root, 'tools/kra-concat-bridge/server.js')), 'A seeded example workflow drives Concat through the MCP bridge.');
assert(n100nDeployment.includes('does not automatically run or publish') || n100nDeployment.includes('tidak otomatis menjalankan atau menerbitkan'), 'Deployment requirements distinguish bundled source from a running service.');
console.log('N100N bundle verification passed: upstream source, runtime-secret isolation, Apache protection, and HTTPS UI shortcut.');
